-- 548: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 10 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_548_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_548_guard;
INSERT INTO _migration_548_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_046' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the inequality 5 − 2x ≥ 1.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x ≥ 2","B. x ≤ 2","C. x ≤ −2","D. x ≥ −2"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Subtract 5 from both sides: −2x ≥ −4. Dividing by the negative number −2 reverses the inequality sign: x ≤ 2. Check: 5 − 2(2) = 1, and 1 ≥ 1 holds. (x ≥ 2 forgets to reverse the sign when dividing by a negative.) Therefore the correct answer is B: x ≤ 2.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_046' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_548_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_047' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the largest integer that satisfies the inequality 4x + 1 < 15.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 4","B. 3.5","C. 3","D. 2"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Subtract 1: 4x < 14, so x < 3.5. The largest whole number below 3.5 is 3. Check: 4(3) + 1 = 13 < 15, while 4(4) + 1 = 17, which fails. (4 rounds 3.5 up without checking the inequality.) Therefore the correct answer is C: 3.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_047' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_548_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_048' AND NOT (q.topic_id IS 'topic_wassce_p2_math_ine' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the inequality (x/2) + 3 > 5.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x > 16","B. x > 1","C. x < 4","D. x > 4"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Subtract 3 from both sides: x/2 > 2. Multiply both sides by the positive number 2: x > 4. Check: (4/2) + 3 = 5, so values above 4 work. (x > 16 adds 3 before doubling: (5 + 3) × 2.) Therefore the correct answer is D: x > 4.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_048' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_548_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_049' AND NOT (q.topic_id IS 'topic_wassce_core_math_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Three consecutive even numbers add up to 78. Taking the smallest number as n, form an equation in n and find the three numbers.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '24, 26 and 28' AND q.explanation IS 'Let the smallest even number be n; the next two consecutive even numbers are n + 2 and n + 4. Their sum gives the equation n + (n + 2) + (n + 4) = 78, so 3n + 6 = 78. Subtracting 6 gives 3n = 72, and dividing by 3 gives n = 24. The three numbers are therefore 24, 26 and 28. Check: 24 + 26 + 28 = 78, as required. Answer: 24, 26 and 28.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Form' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_049' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_548_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_050' AND NOT (q.topic_id IS 'topic_wassce_core_math_numbers' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A shopkeeper increased the price of a bag of rice by 20%. Some weeks later the new price was reduced by 20%. If the original price was GH₵250.00, calculate the final price.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'GH₵240.00' AND q.explanation IS 'After the 20% increase the price is 250 × 1.20 = GH₵300.00. The 20% reduction applies to the new price, not the original: 300 × 0.80 = GH₵240.00. So the final price is GH₵240.00, which is GH₵10.00 below the original price — the two 20% changes do not cancel out because they act on different bases. Equivalently, 250 × 1.20 × 0.80 = 250 × 0.96 = GH₵240.00. Answer: GH₵240.00.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_050' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_046', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the inequality 5 − 2x ≥ 1.', 'multiple_choice', NULL, '["A. x ≥ 2","B. x ≤ 2","C. x ≤ −2","D. x ≥ −2"]', 'B', 'Subtract 5 from both sides: −2x ≥ −4. Dividing by the negative number −2 reverses the inequality sign: x ≤ 2. Check: 5 − 2(2) = 1, and 1 ≥ 1 holds. (x ≥ 2 forgets to reverse the sign when dividing by a negative.) Therefore the correct answer is B: x ≤ 2.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_047', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the largest integer that satisfies the inequality 4x + 1 < 15.', 'multiple_choice', NULL, '["A. 4","B. 3.5","C. 3","D. 2"]', 'C', 'Subtract 1: 4x < 14, so x < 3.5. The largest whole number below 3.5 is 3. Check: 4(3) + 1 = 13 < 15, while 4(4) + 1 = 17, which fails. (4 rounds 3.5 up without checking the inequality.) Therefore the correct answer is C: 3.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_048', 'topic_wassce_p2_math_ine', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the inequality (x/2) + 3 > 5.', 'multiple_choice', NULL, '["A. x > 16","B. x > 1","C. x < 4","D. x > 4"]', 'D', 'Subtract 3 from both sides: x/2 > 2. Multiply both sides by the positive number 2: x > 4. Check: (4/2) + 3 = 5, so values above 4 work. (x > 16 adds 3 before doubling: (5 + 3) × 2.) Therefore the correct answer is D: x > 4.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_049', 'topic_wassce_core_math_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Three consecutive even numbers add up to 78. Taking the smallest number as n, form an equation in n and find the three numbers.', 'calculation', NULL, NULL, '24, 26 and 28', 'Let the smallest even number be n; the next two consecutive even numbers are n + 2 and n + 4. Their sum gives the equation n + (n + 2) + (n + 4) = 78, so 3n + 6 = 78. Subtracting 6 gives 3n = 72, and dividing by 3 gives n = 24. The three numbers are therefore 24, 26 and 28. Check: 24 + 26 + 28 = 78, as required. Answer: 24, 26 and 28.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Form', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_050', 'topic_wassce_core_math_numbers', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A shopkeeper increased the price of a bag of rice by 20%. Some weeks later the new price was reduced by 20%. If the original price was GH₵250.00, calculate the final price.', 'calculation', NULL, NULL, 'GH₵240.00', 'After the 20% increase the price is 250 × 1.20 = GH₵300.00. The 20% reduction applies to the new price, not the original: 300 × 0.80 = GH₵240.00. So the final price is GH₵240.00, which is GH₵10.00 below the original price — the two 20% changes do not cancel out because they act on different bases. Equivalently, 250 × 1.20 × 0.80 = 250 × 0.96 = GH₵240.00. Answer: GH₵240.00.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-core-math-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_wcms3_046', 'q_wcms3_047', 'q_wcms3_048', 'q_wcms3_049', 'q_wcms3_050');
